     * @return list<string>
     */
    public static function language(Grammar $grammar, string $rule): array
    {
        $language = [];
        foreach ($grammar->ruleMap[$rule]->alternatives as $production) {
            $prefixes = [''];
            foreach ($production->symbols as $symbol) {
                $suffixes = $symbol instanceof NonTerminal ? self::language($grammar, $symbol->value) : [$symbol->value()];
                $combined = [];
                foreach ($prefixes as $prefix) {
                    foreach ($suffixes as $suffix) {
                        $combined[] = trim($prefix . ' ' . $suffix);
                    }
                }
                $prefixes = $combined;
            }
            $language = [...$language, ...$prefixes];
        }
        return array_values(array_unique($language));
    }
